import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
// Optimization: occupancy-oriented CTA re-tiling for 2 CTAs/SM. The CTA tile
// narrows from 128x256 / 512 threads to 128x128 / 256 threads (16x16), keeping
// 8x8 register accumulators (64 regs, .maxnreg 128) so two CTAs fit per SM
// (2x256x128 = 64K regs, 2x16KB smem). Independent CTAs interleave on each SM,
// hiding bar.sync / wait_group bubbles and shared-load latency that the single
// 512-thread CTA exposed. Keeps split-K, 4-deep cp.async pipeline over 8-wide
// K-slices, conflict-free vectorized B loads and broadcast scalar A loads.
// Static shared memory: 16KB (A) + 16KB (B) = 32KB per CTA.
.visible .entry matmul_kernel(
    .param .u64 matmul_kernel_param_0,
    .param .u64 matmul_kernel_param_1,
    .param .u64 matmul_kernel_param_2,
    .param .u32 matmul_kernel_param_3,
    .param .u32 matmul_kernel_param_4,
    .param .u32 matmul_kernel_param_5,
    .param .u32 matmul_kernel_param_6
)
.maxnreg 128
{
    .reg .pred %p1, %p2, %p3, %pA4, %pB4;
    .reg .pred %pr<8>;
    .reg .pred %pc<8>;
    .reg .b32 %tx, %ty, %lid, %bx, %by, %bz;
    .reg .b32 %M, %N, %K, %CHUNK, %kk, %kend, %k2, %tmp, %tmp2;
    .reg .b32 %arow, %akc, %brl, %bnc, %grow, %gcol, %akb, %brow, %row, %col;
    .reg .b32 %srcsz, %aoff, %boff, %naoff, %nboff;
    .reg .b64 %gA, %gB, %gC, %addr, %w, %w2, %cstep;
    .reg .b64 %rdAsub, %rdBsub, %rdSA, %rdSB, %rdGA, %rdGB, %rdAp, %rdBp, %rdT;
    .reg .b64 %rdSAn, %rdSBn;
    .reg .f32 %acc<64>;
    .reg .f32 %va<8>;
    .reg .f32 %vb<8>;
    .reg .f32 %v0, %v1, %v2, %v3;
    .shared .align 16 .f32 smA[4096];
    .shared .align 16 .f32 smB[4096];
    ld.param.u64 %gA, [matmul_kernel_param_0];
    ld.param.u64 %gB, [matmul_kernel_param_1];
    ld.param.u64 %gC, [matmul_kernel_param_2];
    ld.param.u32 %M,  [matmul_kernel_param_3];
    ld.param.u32 %N,  [matmul_kernel_param_4];
    ld.param.u32 %K,  [matmul_kernel_param_5];
    ld.param.u32 %CHUNK, [matmul_kernel_param_6];
    mov.u32 %tx, %tid.x;
    mov.u32 %ty, %tid.y;
    mov.u32 %bx, %ctaid.x;
    mov.u32 %by, %ctaid.y;
    mov.u32 %bz, %ctaid.z;
    mov.u64 %rdAsub, smA;
    mov.u64 %rdBsub, smB;
    // lid = ty*32 + tx
    shl.b32 %lid, %ty, 4;
    add.u32 %lid, %lid, %tx;
    // A staging fragment (threads lid<256): row arow = lid>>1, cols akc..akc+3 (akc = (lid&1)*4)
    shr.u32 %arow, %lid, 1;
    and.b32 %akc, %lid, 1;
    shl.b32 %akc, %akc, 2;
    // rdSA = smA + lid*16  (A slice 128x8, row stride 32B; rows (lid>>1), col group (lid&1))
    shl.b32 %tmp, %lid, 4;
    cvt.u64.u32 %w, %tmp;
    add.u64 %rdSA, %rdAsub, %w;
    // B staging fragment: row brl = lid>>5, cols bnc..bnc+3 (bnc = (lid&31)*4)
    shr.u32 %brl, %lid, 5;
    and.b32 %bnc, %lid, 31;
    shl.b32 %bnc, %bnc, 2;
    // rdSB = smB + lid*16  (B slice 8x128, row stride 512B)
    add.u64 %rdSB, %rdBsub, %w;
    // Split-K range for this block: [kk, kend)
    mul.lo.u32 %kk, %bz, %CHUNK;
    add.u32 %kend, %kk, %CHUNK;
    min.u32 %kend, %kend, %K;
    // grow = by*128 + arow ; gcol = bx*256 + bnc
    shl.b32 %grow, %by, 7;
    add.u32 %grow, %grow, %arow;
    shl.b32 %gcol, %bx, 7;
    add.u32 %gcol, %gcol, %bnc;
    // constant byte strides: cstep = 8 rows of B (=N*32), w2 = one C row (=N*4)
    cvt.u64.u32 %cstep, %N;
    shl.b64 %cstep, %cstep, 5;
    cvt.u64.u32 %w2, %N;
    shl.b64 %w2, %w2, 2;
    // cp.async 16B path legal only if K and N are multiples of 4 (alignment)
    and.b32 %tmp, %K, 3;
    setp.eq.u32 %pA4, %tmp, 0;
    and.b32 %tmp, %N, 3;
    setp.eq.u32 %pB4, %tmp, 0;
    // rdGA = gA + (grow*K + kk + akc)*4
    mul.wide.u32 %rdGA, %grow, %K;
    add.u32 %akb, %kk, %akc;
    cvt.u64.u32 %w, %akb;
    add.u64 %rdGA, %rdGA, %w;
    shl.b64 %rdGA, %rdGA, 2;
    add.u64 %rdGA, %rdGA, %gA;
    // rdGB = gB + ((kk+brl)*N + gcol)*4
    add.u32 %brow, %kk, %brl;
    mul.wide.u32 %rdGB, %brow, %N;
    cvt.u64.u32 %w, %gcol;
    add.u64 %rdGB, %rdGB, %w;
    shl.b64 %rdGB, %rdGB, 2;
    add.u64 %rdGB, %rdGB, %gB;
    // zero the 8x8 register accumulators
    mov.f32 %acc0, 0f00000000;
    mov.f32 %acc1, 0f00000000;
    mov.f32 %acc2, 0f00000000;
    mov.f32 %acc3, 0f00000000;
    mov.f32 %acc4, 0f00000000;
    mov.f32 %acc5, 0f00000000;
    mov.f32 %acc6, 0f00000000;
    mov.f32 %acc7, 0f00000000;
    mov.f32 %acc8, 0f00000000;
    mov.f32 %acc9, 0f00000000;
    mov.f32 %acc10, 0f00000000;
    mov.f32 %acc11, 0f00000000;
    mov.f32 %acc12, 0f00000000;
    mov.f32 %acc13, 0f00000000;
    mov.f32 %acc14, 0f00000000;
    mov.f32 %acc15, 0f00000000;
    mov.f32 %acc16, 0f00000000;
    mov.f32 %acc17, 0f00000000;
    mov.f32 %acc18, 0f00000000;
    mov.f32 %acc19, 0f00000000;
    mov.f32 %acc20, 0f00000000;
    mov.f32 %acc21, 0f00000000;
    mov.f32 %acc22, 0f00000000;
    mov.f32 %acc23, 0f00000000;
    mov.f32 %acc24, 0f00000000;
    mov.f32 %acc25, 0f00000000;
    mov.f32 %acc26, 0f00000000;
    mov.f32 %acc27, 0f00000000;
    mov.f32 %acc28, 0f00000000;
    mov.f32 %acc29, 0f00000000;
    mov.f32 %acc30, 0f00000000;
    mov.f32 %acc31, 0f00000000;
    mov.f32 %acc32, 0f00000000;
    mov.f32 %acc33, 0f00000000;
    mov.f32 %acc34, 0f00000000;
    mov.f32 %acc35, 0f00000000;
    mov.f32 %acc36, 0f00000000;
    mov.f32 %acc37, 0f00000000;
    mov.f32 %acc38, 0f00000000;
    mov.f32 %acc39, 0f00000000;
    mov.f32 %acc40, 0f00000000;
    mov.f32 %acc41, 0f00000000;
    mov.f32 %acc42, 0f00000000;
    mov.f32 %acc43, 0f00000000;
    mov.f32 %acc44, 0f00000000;
    mov.f32 %acc45, 0f00000000;
    mov.f32 %acc46, 0f00000000;
    mov.f32 %acc47, 0f00000000;
    mov.f32 %acc48, 0f00000000;
    mov.f32 %acc49, 0f00000000;
    mov.f32 %acc50, 0f00000000;
    mov.f32 %acc51, 0f00000000;
    mov.f32 %acc52, 0f00000000;
    mov.f32 %acc53, 0f00000000;
    mov.f32 %acc54, 0f00000000;
    mov.f32 %acc55, 0f00000000;
    mov.f32 %acc56, 0f00000000;
    mov.f32 %acc57, 0f00000000;
    mov.f32 %acc58, 0f00000000;
    mov.f32 %acc59, 0f00000000;
    mov.f32 %acc60, 0f00000000;
    mov.f32 %acc61, 0f00000000;
    mov.f32 %acc62, 0f00000000;
    mov.f32 %acc63, 0f00000000;
    // skip loop entirely if this partition has no work (uniform branch)
    setp.lt.u32 %p1, %kk, %kend;
    @!%p1 bra STORE;
    // pipeline buffer byte offsets: compute slice (aoff/boff), prefetch slice (naoff/nboff)
    mov.u32 %aoff, 0;
    mov.u32 %boff, 0;
    mov.u32 %naoff, 0;
    mov.u32 %nboff, 0;
    // ---------- prologue: stage slices kk, kk+8, kk+16 into buffers 0,1,2 ----------
    mov.u32 %k2, 0;
PRO_LOOP:
    cvt.u64.u32 %w, %naoff;
    add.u64 %rdSAn, %rdSA, %w;
    cvt.u64.u32 %w, %nboff;
    add.u64 %rdSBn, %rdSB, %w;
    shl.b32 %tmp, %k2, 3;
    add.u32 %tmp, %tmp, %kk;
    setp.lt.u32 %p1, %tmp, %kend;
    @!%p1 bra PRO_COMMIT;
    // ---- stage A frag (threads lid<256, cp.async with zero-fill for OOB) ----
    setp.lt.u32 %p2, %lid, 256;
    @!%p2 bra A_DONE_P;
    sub.s32 %tmp, %K, %akb;
    max.s32 %tmp, %tmp, 0;
    min.s32 %tmp, %tmp, 4;
    shl.b32 %srcsz, %tmp, 2;
    setp.lt.u32 %p1, %grow, %M;
    selp.b32 %srcsz, %srcsz, 0, %p1;
    @!%pA4 bra A_SLOW_P;
    selp.b64 %addr, %rdGA, %gA, %p1;
    cp.async.cg.shared.global [%rdSAn], [%addr], 16, %srcsz;
    bra A_DONE_P;
A_SLOW_P:
    mov.f32 %v0, 0f00000000;
    mov.f32 %v1, 0f00000000;
    mov.f32 %v2, 0f00000000;
    mov.f32 %v3, 0f00000000;
    setp.lt.u32 %p2, %akb, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v0, [%rdGA];
    add.u32 %tmp, %akb, 1;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v1, [%rdGA+4];
    add.u32 %tmp, %akb, 2;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v2, [%rdGA+8];
    add.u32 %tmp, %akb, 3;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v3, [%rdGA+12];
    st.shared.v4.f32 [%rdSAn], {%v0,%v1,%v2,%v3};
A_DONE_P:
    // ---- stage B frag (all 512 threads, one 16B frag each) ----
    sub.s32 %tmp, %N, %gcol;
    max.s32 %tmp, %tmp, 0;
    min.s32 %tmp, %tmp, 4;
    shl.b32 %srcsz, %tmp, 2;
    setp.lt.u32 %p1, %brow, %K;
    selp.b32 %srcsz, %srcsz, 0, %p1;
    @!%pB4 bra B_SLOW_P;
    selp.b64 %addr, %rdGB, %gB, %p1;
    cp.async.cg.shared.global [%rdSBn], [%addr], 16, %srcsz;
    bra B_DONE_P;
B_SLOW_P:
    mov.f32 %v0, 0f00000000;
    mov.f32 %v1, 0f00000000;
    mov.f32 %v2, 0f00000000;
    mov.f32 %v3, 0f00000000;
    setp.lt.u32 %p2, %gcol, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v0, [%rdGB];
    add.u32 %tmp, %gcol, 1;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v1, [%rdGB+4];
    add.u32 %tmp, %gcol, 2;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v2, [%rdGB+8];
    add.u32 %tmp, %gcol, 3;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v3, [%rdGB+12];
    st.shared.v4.f32 [%rdSBn], {%v0,%v1,%v2,%v3};
B_DONE_P:
PRO_COMMIT:
    cp.async.commit_group;
    // advance staging coordinates by one 8-wide K-slice
    add.u32 %akb, %akb, 8;
    add.u32 %brow, %brow, 8;
    add.u64 %rdGA, %rdGA, 32;
    add.u64 %rdGB, %rdGB, %cstep;
    add.u32 %naoff, %naoff, 4096;
    add.u32 %nboff, %nboff, 4096;
    add.u32 %k2, %k2, 1;
    setp.lt.u32 %p1, %k2, 3;
    @%p1 bra PRO_LOOP;
LOOP_K:
    // wait until the oldest in-flight slice has landed (<=2 groups pending), then sync
    cp.async.wait_group 2;
    bar.sync 0;
    // ---------- prefetch slice kk+24 into the rotating buffer ----------
    add.u32 %tmp, %kk, 24;
    setp.lt.u32 %p1, %tmp, %kend;
    @!%p1 bra NO_STAGE_L;
    cvt.u64.u32 %w, %naoff;
    add.u64 %rdSAn, %rdSA, %w;
    cvt.u64.u32 %w, %nboff;
    add.u64 %rdSBn, %rdSB, %w;
    // ---- stage A frag ----
    setp.lt.u32 %p2, %lid, 256;
    @!%p2 bra A_DONE_L;
    sub.s32 %tmp, %K, %akb;
    max.s32 %tmp, %tmp, 0;
    min.s32 %tmp, %tmp, 4;
    shl.b32 %srcsz, %tmp, 2;
    setp.lt.u32 %p1, %grow, %M;
    selp.b32 %srcsz, %srcsz, 0, %p1;
    @!%pA4 bra A_SLOW_L;
    selp.b64 %addr, %rdGA, %gA, %p1;
    cp.async.cg.shared.global [%rdSAn], [%addr], 16, %srcsz;
    bra A_DONE_L;
A_SLOW_L:
    mov.f32 %v0, 0f00000000;
    mov.f32 %v1, 0f00000000;
    mov.f32 %v2, 0f00000000;
    mov.f32 %v3, 0f00000000;
    setp.lt.u32 %p2, %akb, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v0, [%rdGA];
    add.u32 %tmp, %akb, 1;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v1, [%rdGA+4];
    add.u32 %tmp, %akb, 2;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v2, [%rdGA+8];
    add.u32 %tmp, %akb, 3;
    setp.lt.u32 %p2, %tmp, %K;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v3, [%rdGA+12];
    st.shared.v4.f32 [%rdSAn], {%v0,%v1,%v2,%v3};
A_DONE_L:
    // ---- stage B frag ----
    sub.s32 %tmp, %N, %gcol;
    max.s32 %tmp, %tmp, 0;
    min.s32 %tmp, %tmp, 4;
    shl.b32 %srcsz, %tmp, 2;
    setp.lt.u32 %p1, %brow, %K;
    selp.b32 %srcsz, %srcsz, 0, %p1;
    @!%pB4 bra B_SLOW_L;
    selp.b64 %addr, %rdGB, %gB, %p1;
    cp.async.cg.shared.global [%rdSBn], [%addr], 16, %srcsz;
    bra B_DONE_L;
B_SLOW_L:
    mov.f32 %v0, 0f00000000;
    mov.f32 %v1, 0f00000000;
    mov.f32 %v2, 0f00000000;
    mov.f32 %v3, 0f00000000;
    setp.lt.u32 %p2, %gcol, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v0, [%rdGB];
    add.u32 %tmp, %gcol, 1;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v1, [%rdGB+4];
    add.u32 %tmp, %gcol, 2;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v2, [%rdGB+8];
    add.u32 %tmp, %gcol, 3;
    setp.lt.u32 %p2, %tmp, %N;
    and.pred %p2, %p1, %p2;
    @%p2 ld.global.f32 %v3, [%rdGB+12];
    st.shared.v4.f32 [%rdSBn], {%v0,%v1,%v2,%v3};
B_DONE_L:
    // advance staging coordinates by one 8-wide K-slice
    add.u32 %akb, %akb, 8;
    add.u32 %brow, %brow, 8;
    add.u64 %rdGA, %rdGA, 32;
    add.u64 %rdGB, %rdGB, %cstep;
NO_STAGE_L:
    cp.async.commit_group;
    // rdAp = &smA[aoff] + ty*256 (slice row stride 32B), rdBp = &smB[boff] + tx*16
    shl.b32 %tmp, %ty, 8;
    cvt.u64.u32 %w, %tmp;
    add.u64 %rdAp, %rdAsub, %w;
    cvt.u64.u32 %w, %aoff;
    add.u64 %rdAp, %rdAp, %w;
    shl.b32 %tmp, %tx, 4;
    cvt.u64.u32 %w, %tmp;
    add.u64 %rdBp, %rdBsub, %w;
    cvt.u64.u32 %w, %boff;
    add.u64 %rdBp, %rdBp, %w;
    mov.u32 %k2, 0;
K2_LOOP:
    // 8 A values: rows ty*8+i (slice row stride 32B), broadcast within the warp
    ld.shared.f32 %va0, [%rdAp+0];
    ld.shared.f32 %va1, [%rdAp+32];
    ld.shared.f32 %va2, [%rdAp+64];
    ld.shared.f32 %va3, [%rdAp+96];
    ld.shared.f32 %va4, [%rdAp+128];
    ld.shared.f32 %va5, [%rdAp+160];
    ld.shared.f32 %va6, [%rdAp+192];
    ld.shared.f32 %va7, [%rdAp+224];
    // 8 B values as two conflict-free v4 loads: cols tx*4..+3 and 64+tx*4..+3
    ld.shared.v4.f32 {%vb0,%vb1,%vb2,%vb3}, [%rdBp];
    ld.shared.v4.f32 {%vb4,%vb5,%vb6,%vb7}, [%rdBp+256];
    fma.rn.f32 %acc0, %va0, %vb0, %acc0;
    fma.rn.f32 %acc1, %va0, %vb1, %acc1;
    fma.rn.f32 %acc2, %va0, %vb2, %acc2;
    fma.rn.f32 %acc3, %va0, %vb3, %acc3;
    fma.rn.f32 %acc4, %va0, %vb4, %acc4;
    fma.rn.f32 %acc5, %va0, %vb5, %acc5;
    fma.rn.f32 %acc6, %va0, %vb6, %acc6;
    fma.rn.f32 %acc7, %va0, %vb7, %acc7;
    fma.rn.f32 %acc8, %va1, %vb0, %acc8;
    fma.rn.f32 %acc9, %va1, %vb1, %acc9;
    fma.rn.f32 %acc10, %va1, %vb2, %acc10;
    fma.rn.f32 %acc11, %va1, %vb3, %acc11;
    fma.rn.f32 %acc12, %va1, %vb4, %acc12;
    fma.rn.f32 %acc13, %va1, %vb5, %acc13;
    fma.rn.f32 %acc14, %va1, %vb6, %acc14;
    fma.rn.f32 %acc15, %va1, %vb7, %acc15;
    fma.rn.f32 %acc16, %va2, %vb0, %acc16;
    fma.rn.f32 %acc17, %va2, %vb1, %acc17;
    fma.rn.f32 %acc18, %va2, %vb2, %acc18;
    fma.rn.f32 %acc19, %va2, %vb3, %acc19;
    fma.rn.f32 %acc20, %va2, %vb4, %acc20;
    fma.rn.f32 %acc21, %va2, %vb5, %acc21;
    fma.rn.f32 %acc22, %va2, %vb6, %acc22;
    fma.rn.f32 %acc23, %va2, %vb7, %acc23;
    fma.rn.f32 %acc24, %va3, %vb0, %acc24;
    fma.rn.f32 %acc25, %va3, %vb1, %acc25;
    fma.rn.f32 %acc26, %va3, %vb2, %acc26;
    fma.rn.f32 %acc27, %va3, %vb3, %acc27;
    fma.rn.f32 %acc28, %va3, %vb4, %acc28;
    fma.rn.f32 %acc29, %va3, %vb5, %acc29;
    fma.rn.f32 %acc30, %va3, %vb6, %acc30;
    fma.rn.f32 %acc31, %va3, %vb7, %acc31;
    fma.rn.f32 %acc32, %va4, %vb0, %acc32;
    fma.rn.f32 %acc33, %va4, %vb1, %acc33;
    fma.rn.f32 %acc34, %va4, %vb2, %acc34;
    fma.rn.f32 %acc35, %va4, %vb3, %acc35;
    fma.rn.f32 %acc36, %va4, %vb4, %acc36;
    fma.rn.f32 %acc37, %va4, %vb5, %acc37;
    fma.rn.f32 %acc38, %va4, %vb6, %acc38;
    fma.rn.f32 %acc39, %va4, %vb7, %acc39;
    fma.rn.f32 %acc40, %va5, %vb0, %acc40;
    fma.rn.f32 %acc41, %va5, %vb1, %acc41;
    fma.rn.f32 %acc42, %va5, %vb2, %acc42;
    fma.rn.f32 %acc43, %va5, %vb3, %acc43;
    fma.rn.f32 %acc44, %va5, %vb4, %acc44;
    fma.rn.f32 %acc45, %va5, %vb5, %acc45;
    fma.rn.f32 %acc46, %va5, %vb6, %acc46;
    fma.rn.f32 %acc47, %va5, %vb7, %acc47;
